import java.util.ArrayList;
import java.util.Iterator;
import java.util.List;

public class SafeIteratorRemovalDemo {
    public static void main(String[] args) {
        // 1. Safe in-flight removal via Iterator.remove()
        List<String> auditLogs = new ArrayList<>();
        auditLogs.add("INFO: User login");
        auditLogs.add("DEBUG: Cache hit");
        auditLogs.add("DEBUG: Query time 2ms");
        auditLogs.add("WARN: High memory");
        auditLogs.add("DEBUG: Heartbeat ping");

        System.out.println("Before audit purge: " + auditLogs);

        // Purge DEBUG logs using explicit Iterator
        Iterator<String> logIt = auditLogs.iterator();
        while (logIt.hasNext()) {
            String log = logIt.next();
            if (log.startsWith("DEBUG:")) {
                logIt.remove(); // Safely removes current element
            }
        }

        System.out.println("After Iterator.remove: " + auditLogs);

        // 2. Modern equivalent via removeIf()
        auditLogs.removeIf(log -> log.startsWith("WARN:"));
        System.out.println("After removeIf:       " + auditLogs);
    }
}
// Expected Output:
// Before audit purge: [INFO: User login, DEBUG: Cache hit, DEBUG: Query time 2ms, WARN: High memory, DEBUG: Heartbeat ping]
// After Iterator.remove: [INFO: User login, WARN: High memory]
// After removeIf:       [INFO: User login]

