import java.util.ArrayList;
import java.util.Iterator;
import java.util.List;

public class SessionManager {
    static class Session {
        final String userId;
        final long expiresAt;

        Session(String userId, long expiresAt) {
            this.userId = userId;
            this.expiresAt = expiresAt;
        }

        boolean isExpired(long currentTime) {
            return currentTime >= expiresAt;
        }

        @Override
        public String toString() { return userId; }
    }

    public static void purgeExpired(List<Session> sessions, long now) {
        Iterator<Session> it = sessions.iterator();
        while (it.hasNext()) {
            Session s = it.next();
            if (s.isExpired(now)) {
                it.remove(); // Evict safely
            }
        }
    }

    public static void main(String[] args) {
        List<Session> pool = new ArrayList<>();
        pool.add(new Session("Alice", 1000L));
        pool.add(new Session("Bob", 500L));   // Expired at 800
        pool.add(new Session("Charlie", 800L)); // Expired at 800
        pool.add(new Session("Diana", 1200L));

        purgeExpired(pool, 800L);
        System.out.println("Active sessions remaining: " + pool); // [Alice, Diana]
    }
}

