import java.util.List;
import java.util.ArrayList;
import java.util.Iterator;

public class ShortStringFilter {
    public static void filterShortStrings(List<String> words, int minLength) {
        if (words == null) return;
        Iterator<String> it = words.iterator();
        while (it.hasNext()) {
            String w = it.next();
            if (w == null || w.length() < minLength) {
                it.remove();
            }
        }
    }

    public static void main(String[] args) {
        List<String> words = new ArrayList<>(List.of("a", "bb", "ccc", "dddd"));
        filterShortStrings(words, 3);
        System.out.println(words);
    }
}

