import java.util.List;
import java.util.ArrayList;
import java.util.Objects;
import java.util.Iterator;

public class ConsecutiveDuplicateFilter {
    public static <T> void removeConsecutiveDuplicates(List<T> list) {
        if (list == null || list.size() <= 1) return;
        Iterator<T> it = list.iterator();
        T prev = it.next();
        while (it.hasNext()) {
            T curr = it.next();
            if (Objects.equals(prev, curr)) {
                it.remove();
            } else {
                prev = curr;
            }
        }
    }

    public static void main(String[] args) {
        List<String> items = new ArrayList<>(List.of("a", "b", "b", "c", "c", "c", "a"));
        removeConsecutiveDuplicates(items);
        System.out.println(items);
    }
}

