import java.util.Map;
import java.util.HashMap;
import java.util.Iterator;

public class MapKeyEvictor {
    public static void removeEntriesWithPrefix(Map<String, ?> map, String prefix) {
        if (map == null || prefix == null) return;
        Iterator<String> keyIt = map.keySet().iterator();
        while (keyIt.hasNext()) {
            String key = keyIt.next();
            if (key != null && key.startsWith(prefix)) {
                keyIt.remove();
            }
        }
    }

    public static void main(String[] args) {
        Map<String, Integer> map = new HashMap<>();
        map.put("app.port", 8080);
        map.put("test.timeout", 500);
        map.put("app.host", 9000);
        removeEntriesWithPrefix(map, "test.");
        System.out.println(map.size());
    }
}

